from pathlib import Path
import json,hashlib,collections,argparse
parser=argparse.ArgumentParser(description='Regenerate comparison tables from a retained collection.')
parser.add_argument('--collection',type=Path,required=True)
parser.add_argument('--output',type=Path)
args=parser.parse_args()
BASE=args.collection.resolve();RAW=BASE/'raw';OUT=args.output.resolve() if args.output else BASE/'derived'
def load(p):return json.loads(p.read_text())
def write(name,value):(OUT/name).write_text(json.dumps(value,indent=2)+'\n')
rows=load(OUT/'package-findings.json')
candidate=load(RAW/'native-candidate/physical-inventory.json')
delta=[]
for row in rows:
    if row['tree']!='live-buyer':continue
    values=sorted(set(x['version'] for x in candidate if x['name']==row['package']))
    delta.append(dict(package=row['package'],affected_range=row['affected_range'],live_installed_affected_versions=sorted(set(x['version'] for x in row['instances'] if x['installed'])),candidate_installed_versions=values,candidate_audit_reports_package=False,interpretation='Finding absent from candidate audit; runtime compatibility not established.' if row['package']!='ws' else 'Candidate resolutions are outside this affected range, but native alpha.2 declares ws ^8.18.3 and can admit affected versions. Raise the floor to >=8.21.0 and qualify a pinned release.'))
write('native-delta.json',delta)
api=[
 dict(surface='Demos connection, RPC and reads',needed=['connect','nodeCall','rpcCall','getAddress','getAddressInfo','getAddressNonce','getNetworkInfo','getBlockByNumber','getTxByHash','getTransactionHistory'],available=True,evidence='native client declarations and implementation; DemosAdapter and demosRuntime call sites',gap='Transport and response-envelope parity remain unqualified.',owner='local qualification'),
 dict(surface='Ed25519 authority',needed=['connectWallet','crypto.getIdentity','crypto.sign','signMessage'],available=True,evidence='Native Ed25519Authority returns declared public/private key buffers; SDK uses Ed25519 by default.',gap='No key derivation or signature execution was permitted in this assessment.',owner='local qualification; maintainers provide compatibility fixtures'),
 dict(surface='Native DEM transfer',needed=['transfer','confirm','broadcast','waitForNonce'],available=True,evidence='payDem captures these native methods; native client declares all four.',gap='No transfer, confirmation, broadcast, nonce polling or chain execution was performed.',owner='local qualification'),
 dict(surface='Storage Programs',needed=['StorageProgram.deriveStorageAddress','StorageProgram.createStorageProgram','StorageProgram.writeStorage','StorageProgram.publicACL','storagePrograms.sign','storagePrograms.read','tx.confirm','tx.broadcast'],available=True,evidence='Declared native/storage surface; pure-data builder comparisons passed.',gap='Signed payload, fee, failure-envelope and authenticated read parity remain unqualified.',owner='local qualification'),
 dict(surface='Identity reads',needed=['Identities.getIdentities','Identities.getDemosIdsByWeb2Identity','Identities.getDemosIdsByWeb3Identity'],available=True,evidence='Native identity-read surface; existing SDK rejects domain reverse lookup before the call.',gap='Local TypeScript narrowing must reflect the existing domain rejection; no new domain API needed for current behavior.',owner='local type adaptation and qualification'),
 dict(surface='DAHR',needed=['web2.createDahr','Web2Proxy.startProxy'],available=True,evidence='Native client includes both methods and a txHash-bearing result. SDK calls stopProxy only when it exists.',gap='Request, response-evidence, authorization and failure semantics remain unqualified.',owner='local qualification'),
 dict(surface='Raw escape hatch',needed=['broadcastAndWait'],available=False,evidence='DemosRawClient requires this member, but owned runtime source has no call to it; native client has no such member.',gap='Choose an explicit local public-type change or a compatibility wrapper; retaining the exact raw contract would require a compatible member.',owner='local API decision; upstream only if exact raw contract is required'),
 dict(surface='Experimental D402',needed=['D402Client'],available=False,evidence='payD402 dynamically imports the separate demosdk d402/client entry; current generated rails are pay-dem and x402.',gap='Keep the experimental capability separate and optional; a native-compatible companion is an upstream request only if that capability must be retained without the broad tree.',owner='local capability separation; conditional upstream companion'),
 dict(surface='Broader Demos features',needed=['multichain adapters','PQC authority','TLSNotary','full programmatic facade'],available=False,evidence='Native package exports and README intentionally exclude these surfaces.',gap='No current generated native/x402 dependency requirement established for these features.',owner='outside current live migration contract'),
]
write('native-api.json',api)
repairs=[
 dict(package='@multiversx/sdk-core; @near-js/providers',version='13.17.2 -> bip39 3.1.0; 0.2.3 -> node-fetch 2.6.7',condition='D-1: broad tree retained with documented optional omission',required_change='Correct or remove the exact optional pins for bip39 3.1.0 and node-fetch 2.6.7, then rerun the required primary live npm SBOM command. Alternatively qualify a narrow-package migration or an npm-side correction.',why='The omitted nested copies leave optional edges resolving to hoisted bip39 3.1.2 and node-fetch 2.7.0; npm rejects these edges with ESBOMPROBLEMS. The narrow candidate primary SBOM succeeds.',status='open primary SBOM check; conditional U-03 metadata repair or npm follow-up'),
 dict(package='@demosnetwork/demos-native',version='0.1.0-alpha.2',condition='current generated live profile',required_change='Raise the ws floor from ^8.18.3 to >=8.21.0 within the supported major and qualify a pinned release. No missing current-profile runtime API repair was demonstrated.',why='The declared range admits versions in the reported >=8.0.0 <8.21.0 and >=8.0.0 <8.20.1 ranges. Zero findings in the current candidate depend on its resolved ws versions, not a safe declared floor.',status='upstream dependency floor repair and local qualification required'),
 dict(package='@demosnetwork/demos-native release status',version='latest: 0.1.0-alpha.1; next: 0.1.0-alpha.2',condition='release selection by the owner and Hayk',required_change='The owner and Hayk must choose whether to pin exactly alpha.2 for qualification or request a stable latest release by 2026-11-06; carry the ws floor repair into the selected release.',why='The newest published version is tagged next and is a prerelease; a zero-finding resolution does not settle its production release status.',status='owner and Hayk decision required'),
 dict(package='@kynesyslabs/demosdk',version='4.0.16; 4.0.18 lock-only control',condition='broad package retained in shipped production tree',required_change='Separate unused chain, proof, attestation, bridge and crypto toolchains from native installs; alternatively deliver and qualify repaired parent dependency chains below.',why='The live installed tree retains 75 affected package entries. Lock-only controls of 4.0.16 and 4.0.18 both report 73 package findings with development and optional dependencies omitted; neither control is the generated composition or an API compatibility qualification.',status='conditional upstream repair'),
 dict(package='@metaplex-foundation/js -> @irys/sdk -> aptos',version='aptos 1.8.5',condition='legacy chain toolchain retained',required_change='Replace the legacy Aptos client and its axios 0.27.2/form-data 4.0.0 dependencies with a supported, qualified parent chain; current leaf candidates include axios 0.34.0 or 1.20.0 and form-data 4.0.6, but parent API compatibility must be tested.',why='This installed chain carries critical inherited and multipart dependency findings; a root-level update does not change these nested copies.',status='conditional upstream repair; no safe upgrade qualified'),
 dict(package='@cosmjs/stargate -> @confio/ics23 -> protobufjs',version='protobufjs 6.11.6',condition='Cosmos toolchain retained',required_change='Move the proof package to a supported protobufjs generation/runtime with a version outside the listed affected ranges; the currently published 7.x tag is 7.6.6. Regenerate and qualify the proof encode/decode contract.',why='The old nested major is pinned by its parent range and carries a critical dependency finding.',status='conditional upstream repair; major compatibility required'),
 dict(package='node-forge',version='1.4.0',condition='RSA verification retained',required_change='Remove the unused RSA dependency from the native path, or supply a corrected and qualified RSA verification implementation/release.',why='The newest published version remains inside the reported range; default native Ed25519 operation does not establish use of the affected RSA verifier.',status='conditional upstream repair; no published leaf fix established'),
 dict(package='@solana/web3.js -> bigint-buffer',version='1.98.0 -> 1.1.5',condition='Solana toolchain retained',required_change='Replace the unsupported native integer conversion dependency, or move the parent to a qualified implementation that does not depend on it; remove eager non-native provider imports from the identity read path.',why='The newest bigint-buffer version is still the affected version, and its module loads through abstraction provider registration.',status='conditional upstream repair; no published leaf fix established'),
 dict(package='@coral-xyz/anchor; @project-serum/anchor; @simplewebauthn/server',version='toml 3.0.0; server 11.0.0',condition='program tooling or WebAuthn capability retained',required_change='Upgrade or replace parent packages so TOML parsing and attestation verification resolve outside the listed affected ranges. Current leaf releases are toml 5.0.1 and server 14.0.3; qualify their changed APIs.',why='Both classes of dependency finding remain installed although their affected operations were not established in the native import path.',status='conditional upstream repair; major compatibility required'),
 dict(package='Legacy asset, NEAR, MultiversX, Bitcoin and Ethereum toolchains',version='Exact paths and affected ranges in both finding tables',condition='remaining broad features retained',required_change='Modernize parent APIs and locks for affected base-x, bn.js, csv-parse, elliptic, secp256k1, stream-json, underscore, uuid and ws instances; select versions outside every applicable range and qualify callers. Elliptic has no newer clean published release established.',why='Nested old major versions and parent constraints remain; npm fix signals are not compatibility evidence.',status='conditional upstream repair; no safe override proposed'),
 dict(package='@demosnetwork/demos-native companion / raw API',version='not supplied by alpha.2',condition='exact broadcastAndWait raw contract or experimental D402 without broad dependencies is required',required_change='Specify the compatibility contract first, then request the missing method or a separately optional native-compatible D402 client.',why='These gaps do not require a new upstream API for the current generated native/x402 profile when settled locally.',status='conditional upstream API request'),
]
write('upstream-actions.json',repairs)
# Inventory comparison is explicit because the lock-only omit output is incomplete here.
checks=[]
for name in ['live-buyer','live-seller']:
    physical=load(RAW/name/'sbom-installed.cdx.json');locked=load(RAW/name/'sbom-lock.stdout.log')
    def keys(b):return {(p['value'],c['name'],c['version']) for c in b['components'] for p in c['properties'] if p['name']=='cdx:npm:package:path'}
    pkeys,lkeys=keys(physical),keys(locked)
    checks.append(dict(tree=name,physical_instances=len(pkeys),lock_only_omit_optional_components=len(lkeys),only_physical=[dict(location=x[0],package=x[1],version=x[2]) for x in sorted(pkeys-lkeys)],only_lock=[dict(location=x[0],package=x[1],version=x[2]) for x in sorted(lkeys-pkeys)],interpretation='Lock-only omission is not a complete installed-tree SBOM; physical instance export retains the original range conflicts.'))
write('sbom-comparison.json',checks)
print('supplemental data written')
